/// <summary>
///     Creates the <c>InventTransferParmLine</c> records that are eligible for picking.
///     where extraction status=”Ready for extract” only.
/// </summary>
/// <param name="_inventTransferParmTable">
///     Current <c>InventTransferParmTable</c> record that will be used to retrieve all the
///     <c>InventTransferLine</c> records.
/// </param>
public static void METCreatePickLines(InventTransferParmTable _inventTransferParmTable)
{
    METInventTransferParmLineCreate::newFromParameters(_inventTransferParmTable).createPickLines();
}
